_sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_7 = Integer(7); _sage_const_6 = Integer(6); _sage_const_200000 = Integer(200000); _sage_const_4 = Integer(4); _sage_const_50000 = Integer(50000); _sage_const_8 = Integer(8); _sage_const_201 = Integer(201); _sage_const_200 = Integer(200); _sage_const_60 = Integer(60); _sage_const_3000 = Integer(3000); _sage_const_1025 = Integer(1025); _sage_const_1020 = Integer(1020); _sage_const_14 = Integer(14); _sage_const_30 = Integer(30); _sage_const_32 = Integer(32); _sage_const_100000 = Integer(100000); _sage_const_127 = Integer(127); _sage_const_100 = Integer(100); _sage_const_13137 = Integer(13137); _sage_const_4096 = Integer(4096)
