            if result:
                print(f"\n[!!!] SUCCESS!")
                print(f"[!!!] Message: {result}")
                response = send_message(s, result)
                print(f"[!!!] Server response: {response}")
                
                if "flag" in response.lower() or "ASIS" in response:
                    print("\n" + "="*_sage_const_60 )
